let monthRows=[],monthBudgetTotals=[],monthPage=1,monthEpoch=0;
function monthlyRender(){monthBody.replaceChildren();for(const x of monthRows.slice((monthPage-1)*10,monthPage*10)){const tr=monthlyNode('tr');for(const k of monthKeys)tr.append(monthlyNode('td',x[k]??'—'));monthBody.append(tr)}monthStatus.textContent='Page '+monthPage+' · '+monthRows.length+' ligne(s)';monthPrev.disabled=monthPage===1;monthNext.disabled=monthPage*10>=monthRows.length;monthExport.disabled=!monthRows.length;renderBudgetTotals()}
async function loadMonthly(){const id=++monthEpoch,t=token;monthRows=[];monthBudgetTotals=[];monthPage=1;monthlyRender();const q=new URLSearchParams({start:monthStart.value,end:monthEnd.value,product:monthProduct.value,currency:monthCurrency.value});const r=await fetch('/api/admin/direction/saas-monthly?'+q,{headers:{Authorization:'Bearer '+t}});const d=await r.json();if(id!==monthEpoch||!token||t!==token)return;if(!r.ok)throw Error(d.error);const p=monthProduct.value;monthProduct.replaceChildren(new Option('Tous les produits',''));for(const [id,name] of Object.entries(d.products))monthProduct.append(new Option(name,id));monthProduct.value=p;monthRows=d.items.map(x=>({...x,budget_alert:x.over_budget?'Dépassement':x.cost_budget===null?'Non défini':'—'}));monthBudgetTotals=d.budget_totals;monthlyRender()}
monthlyForm.onsubmit=async e=>{e.preventDefault();if(token)try{await loadMonthly()}catch(e){notice(e.message)}};
for(const f of [monthStart,monthEnd,monthProduct,monthCurrency])f.onchange=()=>{monthEpoch++;monthRows=[];monthBudgetTotals=[];monthPage=1;monthlyRender()};
monthPrev.onclick=()=>{if(token&&monthPage>1){monthPage--;monthlyRender()}};monthNext.onclick=()=>{if(token&&!monthNext.disabled){monthPage++;monthlyRender()}};
monthExport.onclick=()=>{if(!token||!monthRows.length)return;const esc=v=>{let s=String(v??'');if(/^[\s]*[=+\-@]/.test(s)||/^[\t\r\n]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};const csv=[monthHeaders,...monthRows.map(x=>monthKeys.map(k=>x[k]))].map(r=>r.map(esc).join(';')).join('\r\n');const a=monthlyNode('a'),url=URL.createObjectURL(new Blob(['\uFEFF',csv],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='dsig-performance-saas.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
