function flowTable(root,title,items){root.replaceChildren(commercialNode('h3',title));const wrap=commercialNode('div'),table=commercialNode('table'),head=commercialNode('thead'),tr=commercialNode('tr'),body=commercialNode('tbody');wrap.className='table-wrap';wrap.tabIndex=0;wrap.setAttribute('role','region');wrap.setAttribute('aria-label',title);for(const [,label] of flowColumns){const th=commercialNode('th',label);th.scope='col';tr.append(th)}head.append(tr);for(const x of items){const r=commercialNode('tr');for(const [key] of flowColumns)r.append(commercialNode('td',String(x[key]??'À vérifier')));body.append(r)}if(!items.length){const r=commercialNode('tr'),td=commercialNode('td','Aucun résultat.');td.colSpan=flowColumns.length;r.append(td);body.append(r)}table.append(head,body);wrap.append(table);root.append(wrap)}
function flowUrl(format='json'){return '/api/admin/direction/financial-consolidation?'+new URLSearchParams({year:flowYear.value,q:flowSearch.value,page:flowPage,format})}
async function loadConsolidation(){const t=token,id=++flowEpoch;flowPrev.disabled=flowNext.disabled=flowExport.disabled=true;flowAnnual.replaceChildren();flowMonthly.replaceChildren();try{const r=await fetch(flowUrl(),{headers:{Authorization:'Bearer '+t}}),d=await r.json();if(!t||t!==token||id!==flowEpoch)return;if(!r.ok)throw Error(d.error);flowTable(flowAnnual,'Synthèse annuelle complète',d.annual);flowTable(flowMonthly,'Détail mensuel',d.items);flowStatus.textContent=d.total+' ligne(s) · Page '+d.page+' · Au '+d.as_of;flowPrev.disabled=d.page===1;flowNext.disabled=d.page*10>=d.total;flowExport.disabled=false}catch(e){if(t===token&&id===flowEpoch)flowStatus.textContent=e.message}}
function flowFilter(){clearTimeout(flowTimer);flowEpoch++;flowPage=1;flowExport.disabled=flowPrev.disabled=flowNext.disabled=true;flowTimer=setTimeout(()=>{if(token)loadConsolidation()},200)}flowYear.onchange=flowSearch.oninput=flowFilter;flowPrev.onclick=()=>{if(token&&flowPage>1){flowPage--;loadConsolidation()}};flowNext.onclick=()=>{if(token&&!flowNext.disabled){flowPage++;loadConsolidation()}};
flowExport.onclick=async()=>{const t=token,id=flowEpoch;if(!t)return;try{const r=await fetch(flowUrl('csv'),{headers:{Authorization:'Bearer '+t}});if(!r.ok)throw Error('Export indisponible.');const blob=await r.blob();if(t!==token||id!==flowEpoch)return;const url=URL.createObjectURL(blob),a=commercialNode('a');a.href=url;a.download='consolidation-'+flowYear.value+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){if(t===token&&id===flowEpoch)flowStatus.textContent=e.message}};
